from collections import Counter

def correct_transform(grid):
    """Fill gaps between runs of pattern color with 2"""

    # Find background (most common color)
    counts = Counter(cell for row in grid for cell in row)
    bg_color = counts.most_common(1)[0][0]

    # Find pattern color (second most common, or any non-bg)
    if counts.most_common(2) and counts.most_common(2)[1][1] > 0:
        pattern_color = counts.most_common(2)[1][0]
    else:
        pattern_color = max(set(counts.keys()) - {bg_color})

    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # For each bg cell, check if it's a gap between pattern clusters (1 cell wide)
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        for r in range(H):
            for c in range(W):
                if out[r][c] != bg_color:
                    continue

                # Check if pattern cells exist on BOTH sides along this direction
                has_pattern_before = False
                has_pattern_after = False

                # Look in negative direction
                for step in range(1, max(H, W)):
                    nr, nc = r - step * dr, c - step * dc
                    if not (0 <= nr < H and 0 <= nc < W):
                        break
                    if out[nr][nc] == pattern_color or out[nr][nc] == 2:
                        has_pattern_before = True
                        break
                    if out[nr][nc] != bg_color:
                        break  # Hit something else, stop

                has_pattern_after = False
                for step in range(1, max(H, W)):
                    nr, nc = r + step * dr, c + step * dc
                    if not (0 <= nr < H and 0 <= nc < W):
                        break
                    if out[nr][nc] == pattern_color or out[nr][nc] == 2:
                        has_pattern_after = True
                        break
                    if out[nr][nc] != bg_color:
                        break  # Hit something else, stop

                # If pattern on both sides, fill with 2 (gap is already 1 cell)
                if has_pattern_before and has_pattern_after:
                    out[r][c] = 2

    return out

