def get_neighbors_with_pattern(grid, r, c, dr, dc):
    """For a direction (dr, dc), find the first non-bg cell and its distance"""
    bg = grid[r][c]
    for step in range(1, 30):  # max reasonable distance
        nr, nc = r - step * dr, c - step * dc
        if not (0 <= nr < 14 and 0 <= nc < 29):
            return None, float('inf')
        if grid[nr][nc] == bg:
            continue
        if grid[nr][nc] > 0:  # pattern
            return (nr, nc), step
    return None, float('inf')

